#!/usr/bin/env bash
# Regenerates src/curand/sobol_joe_kuo.inc (the Sobol direction numbers of libcurand's JOEKUO6 sets)
# from the new-joe-kuo-6.21201 data, as SciPy ships it (scipy/stats/_sobol_direction_numbers.npz).
# Needs python3 with numpy and scipy (or the .npz path as the first argument).
#
# The data: S. Joe and F. Y. Kuo, "Constructing Sobol sequences with better two-dimensional
# projections", SIAM J. Sci. Comput. 30, 2635-2654 (2008); https://web.maths.unsw.edu.au/~fkuo/sobol/
# (BSD-style license, reproduced in the generated file).
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
NPZ="${1:-$(python3 -c 'import os, scipy.stats; print(os.path.join(os.path.dirname(scipy.stats.__file__), "_sobol_direction_numbers.npz"))')}"
OUT="$ROOT/src/curand/sobol_joe_kuo.inc"
python3 -I - "$NPZ" "$OUT" <<'EOF'
import sys
import numpy as np
data = np.load(sys.argv[1])
poly, vinit = data["poly"], data["vinit"]
dims = 20000
words = []
for d in range(1, dims):  # dimension 0 is van der Corput's, without data
    p = int(poly[d])
    s = p.bit_length() - 1
    a = (p >> 1) & ((1 << (s - 1)) - 1)
    words.append(s | a << 5)
    words.extend(int(m) for m in vinit[d][:s])
with open(sys.argv[2], "w") as f:
    f.write("""// Generated by tools/gen_sobol_table.sh: the Sobol direction numbers of dimensions 2 to 20000 from
// new-joe-kuo-6.21201. For each dimension, a word s | a << 5 (the primitive polynomial's degree s and
// its inner coefficients a), then its initial direction numbers m_1 .. m_s.
//
// Copyright (c) 2008, Frances Y. Kuo and Stephen Joe
// All rights reserved.
//
// Redistribution and use in source and binary forms, with or without modification, are permitted
// provided that the following conditions are met:
//
//   * Redistributions of source code must retain the above copyright notice, this list of conditions
//     and the following disclaimer.
//   * Redistributions in binary form must reproduce the above copyright notice, this list of
//     conditions and the following disclaimer in the documentation and/or other materials provided
//     with the distribution.
//   * Neither the names of the copyright holders nor the names of the University of New South Wales
//     and the University of Waikato and its contributors may be used to endorse or promote products
//     derived from this software without specific prior written permission.
//
// THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS ``AS IS'' AND ANY EXPRESS OR IMPLIED WARRANTIES,
// INCLUDING, BUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A
// PARTICULAR PURPOSE ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT HOLDERS BE LIABLE FOR ANY DIRECT,
// INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT LIMITED TO,
// PROCUREMENT OF SUBSTITUTE GOODS OR SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS
// INTERRUPTION) HOWEVER CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY,
// OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN
// IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.
""")
    for i in range(0, len(words), 16):
        f.write(",".join(str(w) for w in words[i:i + 16]) + ",\n")
EOF
echo "==> $OUT"
